package de.mika.promptwerk;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;
import android.app.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
import java.io.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @LooperMode(LooperMode.Mode.PAUSED)
public class Revision30Tests {
 MainActivity a;
 @Before public void setup(){RuntimeEnvironment.getApplication().getSharedPreferences("library",0).edit().clear().commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();}
 @After public void close(){a.onDestroy();}
 String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=" "+text(((ViewGroup)v).getChildAt(i));return s;}
 int buttons(View v){int n=v instanceof Button?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)n+=buttons(((ViewGroup)v).getChildAt(i));return n;}
 Button find(View v,String name){if(v instanceof Button&&((Button)v).getText().toString().equals(name))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),name);if(b!=null)return b;}return null;}
 void layout(View v,int h){v.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,360,h);}
 @Test public void overviewShowsAllKindsWithoutButtonsAndOpensExactEntry(){
 MainActivity.Item done=a.items.get(0);done.archived=true;String before=a.editor.getText().toString();a.showOverview();assertEquals(a.items.size(),a.overviewRows.getChildCount());assertEquals(0,buttons(a.overviewDialog.getWindow().getDecorView()));assertTrue(text(a.overviewRows).contains("Erledigt · Baustein"));
 for(int i=0;i<a.overviewRows.getChildCount();i++)if(text(a.overviewRows.getChildAt(i)).contains(done.title)){a.overviewRows.getChildAt(i).performClick();break;}
 assertSame(done,a.entryWindow.item);assertEquals(before,a.editor.getText().toString());a.entryWindow.dialog.dismiss();a.overviewSearch.setText(done.title);assertEquals(1,a.overviewRows.getChildCount());a.overviewRows.getChildAt(0).performLongClick();assertNotNull(ShadowAlertDialog.getLatestAlertDialog());assertEquals("Zurückholen",ShadowAlertDialog.getLatestAlertDialog().getListView().getAdapter().getItem(3));
 }
 @Test public void completedNeverLeaksIntoMainSearchAndRestoreRefreshesBothViews(){MainActivity.Item done=a.items.get(0);done.archived=true;a.persist();a.search.setText(done.title);assertFalse(text(a.rows).contains(done.title));a.showOverview();a.overviewSearch.setText(done.title);assertEquals(1,a.overviewRows.getChildCount());a.setArchived(done,false);assertTrue(text(a.rows).contains(done.title));assertFalse(text(a.overviewRows).contains("Erledigt ·"));}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void mainCardActionsFitOneRowAndEditorUsesNaturalWidths()throws Exception{
 View main=a.findViewById(android.R.id.content);layout(main,800);View card=a.rows.getChildAt(0);Button copy=find(card,"Kopieren"),paste=find(card,"Einfügen"),done=find(card,"Erledigt");assertEquals(copy.getTop(),paste.getTop());assertEquals(copy.getParent(),done.getParent());assertTrue(((View)copy.getParent()).getWidth()<=card.getWidth());assertTrue(copy.getWidth()<a.dp(90));assertEquals(3,((TextView)((ViewGroup)card).getChildAt(2)).getMaxLines());assertEquals(16f,a.prompts.getTextSize(),0.1f);screenshot(main,"Hauptseite",800);
 a.showDraft();layout(main,800);assertEquals(a.dp(38),find(a.editPane,"Kopieren").getHeight());assertTrue(find(a.editPane,"Teilen").getWidth()<a.dp(90));
 a.showOverview();View decor=a.overviewDialog.getWindow().getDecorView();layout(decor,800);screenshot(decor,"Liste",800);
 }
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void smallEditorLabelsRenderWhenOpenedBeforeLayout()throws Exception{a.showDraft();View content=a.findViewById(android.R.id.content);Shadows.shadowOf(Looper.getMainLooper()).idle();layout(content,800);Button b=find(a.editPane,"Kopieren");assertEquals("Kopieren",b.getText().toString());assertNotNull(b.getLayout());assertTrue(b.getBaseline()>0&&b.getBaseline()<b.getHeight());screenshot(content,"Kleiner-Editor",800);}
 @Test public void overviewQueryAndUnsavedEntrySurviveRecreation()throws Exception{a.showOverview();a.overviewSearch.setText("Klar");a.overviewRows.getChildAt(0).performClick();a.entryWindow.setReading(false);a.entryWindow.text.setText("Nicht verlieren");Bundle saved=new Bundle();a.onSaveInstanceState(saved);a.onDestroy();a=Robolectric.buildActivity(MainActivity.class).create(saved).start().resume().visible().get();assertNotNull(a.overviewDialog);assertEquals("Klar",a.overviewSearch.getText().toString());assertEquals("Nicht verlieren",a.entryWindow.text.getText().toString());}
 WindowInsets insets(int keyboard){return new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),Insets.of(0,24,0,24)).setInsets(WindowInsets.Type.ime(),Insets.of(0,0,0,keyboard)).setVisible(WindowInsets.Type.ime(),keyboard>0).build();}
 void verifyKeyboard(Window window,EditText editor,String screenshot)throws Exception{View decor=window.getDecorView();View body=((ViewGroup)window.findViewById(android.R.id.content)).getChildAt(0);layout(decor,800);int originalHeight=editor.getHeight();body.dispatchApplyWindowInsets(insets(300));layout(decor,800);Button save=find(body,"Speichern");int[] at=new int[2];save.getLocationInWindow(at);assertTrue("Save above keyboard",at[1]+save.getHeight()<=500);assertTrue("Editor shrinks",editor.getHeight()<originalHeight);assertTrue("Text field remains usable",editor.getHeight()>0);int padding=body.getPaddingBottom();body.dispatchApplyWindowInsets(insets(300));layout(decor,800);assertEquals("No accumulating padding",padding,body.getPaddingBottom());screenshot(decor,screenshot,800);body.dispatchApplyWindowInsets(insets(0));layout(decor,800);assertTrue("Editor grows when keyboard hides",editor.getHeight()>0);assertEquals(a.dp(8)+24,body.getPaddingBottom());}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void bothFullScreenEditorsKeepSaveAboveKeyboardAndRestoreInsets()throws Exception{a.editor.setText("Entwurf bleibt erhalten");a.expandEditor();verifyKeyboard(a.expandedDialog.getWindow(),a.editor,"Vollbild-Tastatur");a.expandedDialog.dismiss();assertEquals("Entwurf bleibt erhalten",a.editor.getText().toString());a.newEntry();a.entryWindow.title.setText("Neuer Eintrag");a.entryWindow.text.setText("Eintrag bleibt erhalten");verifyKeyboard(a.entryWindow.dialog.getWindow(),a.entryWindow.text,"Eintrag-Tastatur");assertEquals("Eintrag bleibt erhalten",a.entryWindow.text.getText().toString());}
 @Test @Config(sdk=28) public void oldAndroidUsesResizeWithoutFullscreenFlags(){a.expandEditor();Window w=a.expandedDialog.getWindow();assertEquals(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE,w.getAttributes().softInputMode&WindowManager.LayoutParams.SOFT_INPUT_MASK_ADJUST);assertEquals(0,w.getAttributes().flags&WindowManager.LayoutParams.FLAG_FULLSCREEN);}
 void screenshot(View v,String name,int h)throws Exception{Bitmap b=Bitmap.createBitmap(360,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(OutputStream out=new FileOutputStream("tests/Promptwerk-3.0-"+name+".png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
}
